  const text = await res.text();
  let json = null; try { json = JSON.parse(text); } catch { /* not JSON */ }
  if (!res.ok) return { ok: false, error: `GitHub answered ${res.status}: ${json?.message ?? text.slice(0, 200)}` };
  return { ok: true, json };
